package com.eventhub.controller; import com.eventhub.dto.NotificationResponse; import com.eventhub.service.NotificationService; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/notifications") @RequiredArgsConstructor public class NotificationController {private final NotificationService service; @GetMapping public Page<NotificationResponse> list(Authentication a,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.list(a.getName(),page,size);} @GetMapping("/unread-count") public long unread(Authentication a){return service.unread(a.getName());} @PutMapping("/{id}/read") public void read(Authentication a,@PathVariable Long id){service.read(a.getName(),id);} @PutMapping("/read-all") public void readAll(Authentication a){service.readAll(a.getName());}}
